mapper.insert:
INSERT INTO bt_user ( user_id, user_name, real_name, user_type, user_icon, default_tenant_id, phone_no, email, password, system_code, ext_user_id, create_tenant_id, creator_id, created_time, status_cd, updator_id, updated_time, remark, is_locked, login_fail_count, user_state, user_exp_date, pwd_updated_time ) SELECT #{dto.userId}, #{dto.userName}, #{dto.realName}, #{dto.userType}, #{dto.userIcon}, #{dto.defaultTenantId}, #{dto.phoneNo}, #{dto.email}, #{dto.password}, #{dto.systemCode}, #{dto.extUserId}, #{dto.createTenantId}, #{dto.creatorId}, , #{dto.statusCd}, #{dto.updatorId}, , #{dto.remark}, #{dto.isLocked}, #{dto.loginFailCount}, #{dto.userState}, #{dto.userExpDate},
WHERE NOT EXISTS ( SELECT 1 FROM bt_user WHERE status_cd = '00A' AND system_code = #{dto.systemCode} AND ( user_name = #{dto.userName}
OR ext_user_id = #{dto.extUserId}
) )

mapper.select:
SELECT a.user_id, a.user_name, a.real_name, a.phone_no, a.email, a.remark, a.system_code, a.created_time, a.create_tenant_id, a.is_locked, a.user_state, a.user_exp_date, (SELECT b.user_role FROM bt_tenant_user b WHERE a.user_id = b.user_id AND b.tenant_id = #{tenantId} and b.status_cd = '00A') AS "userRole" FROM bt_user a WHERE 1=1
AND a.create_tenant_id = #{query.creatTenantId}
ORDER BY a.updated_time DESC

SELECT user_id, user_name, real_name, phone_no, email, password, default_tenant_id, user_icon,
       is_locked, login_fail_count, user_state, user_exp_date, user_type, pwd_updated_time
FROM bt_user
WHERE status_cd = '00A'
  AND system_code = #{systemCode}
  AND user_name = #{userName}

